def solve_small_cases(m_max):
    results = []
    for m in range(2, m_max + 1):
        s1 = 0
        for n in range(1, m):
            term1 = m**n
            for k in range(1, n + 1):
                term1 /= (m + k)
            s1 += term1

        s2 = 0
        for n in range(1, m):
            term2 = 1
            for k in range(1, n + 1):
                term2 *= (m - k) / m
            s2 += term2

        results.append((m, s1 - s2))
    return results

res = solve_small_cases(20)
for m, diff in res:
    print(f"M={m}: {diff:.10f}")

def solve(M):
    S1 = 0
    for n in range(1, M):
        denom = 1
        for k in range(1, n + 1):
            denom *= (M + k)
        S1 += (M**n) / denom

    S2 = 0
    prod = 1
    for n in range(1, M):
        prod *= (1 - n/M)
        S2 += prod

    return S1, S2, S1 - S2

for M in range(2, 11):
    S1, S2, diff = solve(M)
    print(f"M={M}: S1={S1:.4f}, S2={S2:.4f}, diff={diff:.4f}")

