def solve_stable_v3(m):
    s1 = 0
    t1 = 1
    for n in range(1, m):
        t1 *= m / (m + n)
        s1 += t1

    s2 = 0
    t2 = 1
    for n in range(1, m):
        t2 *= (m - n) / m
        s2 += t2

    return s1 - s2

